#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 2e6 + 5;

int n;
ll m, a[N], ans;

void init() {}

namespace brute_force
{
	const ll N1 = 5005;

	ll f[N1][N1], g[N1][N1], d[N1][N1];

	void solve1()
	{
		cin >> n >> m;
		for (int i = 1; i <= n; ++i)
			cin >> a[i];
		memset(f, 0, sizeof f);
		memset(g, 0, sizeof g);
		memset(d, 0x3f, sizeof d);
		ans = 0;
		for (int i = n, j = n; i >= 1; --i)
		{
			while (j > i && a[j] - a[i] > m)
			{
				for (int k = j + 1; k <= n; ++k)
				{
					if (d[j][k] <= n)
						g[k][d[j][k]] -= f[j][k];
				}
				--j;
			}
			// cerr << i << ' ' << j << endl << endl;
			for (int k = j + 1; k <= n; ++k)
			{
				if (d[j][k] <= n)
					g[k][d[i][k] = d[j][k] + 1] += f[i][k] += g[k][d[j][k]];
			}
			for (int k = i + 1; k <= j; ++k)
				g[k][1] += f[i][k] = d[i][k] = 1;
			// for (int x = 1; x <= n; ++x)
			// {
			// 	for (int y = 1; y <= n; ++y)
			// 		cerr << g[x][y] << " \n"[y == n];
			// }
			// cerr << endl;
			// for (int x = 1; x <= n; ++x)
			// {
			// 	for (int y = 1; y <= n; ++y)
			// 		cerr << f[x][y] << " \n"[y == n];
			// }
			// cerr << endl;
		}
		for (int i = 1; i <= n; ++i)
		{
			for (int j = 1; j <= n; ++j)
				ans += f[i][j] == 2;
		}
		cout << ans << endl;
	}
}

void solve()
{
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1, __;
	cin >> __ >> _;
	init();
	while (_--)
	{
		if (__ <= 10)
			brute_force::solve1();
		else
			solve();
	}
	return 0;
}

